"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[77155],{18380:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>d,frontMatter:()=>o,metadata:()=>a,toc:()=>l});const a=JSON.parse('{"id":"tianya/lastnightpractice","title":"","description":"Finally escaped that terrible place. Finally understand why the whole nation loves to denounce that terrible place. I\'ve heard quite a few jokes about that place these past few days -- some things are truly brazen. I can talk about them in some officials\' thread later. Today\'s topic: first, of course, men must be denounced. Back in Beijing, not denouncing men is impossible.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/lastnightpractice.md","sourceDirName":"tianya","slug":"/tianya/lastnightpractice","permalink":"/tianya/lastnightpractice","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"lastnightpractice","title":"","hide_table_of_contents":true},"sidebar":"tianyaSidebar","previous":{"title":"\u8bf7\u95ee\uff1a\u672c\u5973\u8fd9\u79cd\u884c\u4e3a\u7b97\u4e0d\u7b97\u8fc7\u5206\uff0c\u8fd8\u662f\u53ef\u4ee5\u63a5\u53d7\uff1f","permalink":"/tianya/meacceptable"},"next":{"title":"\u6d17\u5b8c\u6fa1\u4e0a\u6765\uff0c\u7ec8\u4e8e\u53d1\u73b0\uff0c\u672c\u5973\u4e0d\u53ef\u80fd\u7ee7\u7eed\u5728\u8fd9\u53d1\u751f\u5173\u7cfb\u4e86\uff01","permalink":"/tianya/afterbath"}}');var i=n(74848),s=n(28453);const o={id:"lastnightpractice",title:"",hide_table_of_contents:!0},r="This Lady's Practice Last Night: Men = Menstrual Pads = Fast-Moving Consumer Goods",c={},l=[];function h(e){const t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"this-ladys-practice-last-night-men--menstrual-pads--fast-moving-consumer-goods",children:"This Lady's Practice Last Night: Men = Menstrual Pads = Fast-Moving Consumer Goods"})}),"\n",(0,i.jsx)(t.p,{children:"Finally escaped that terrible place. Finally understand why the whole nation loves to denounce that terrible place. I've heard quite a few jokes about that place these past few days -- some things are truly brazen. I can talk about them in some officials' thread later. Today's topic: first, of course, men must be denounced. Back in Beijing, not denouncing men is impossible."}),"\n",(0,i.jsx)(t.p,{children:"Last night, still in that terrible central province, naturally one must celebrate wildly before departing. When the drinking got merry, this lady deliberately challenged the men present. This lady proposed a thesis: men are cheap goods, with licentiousness written all over their faces! If you don't believe it, you can verify through immediate practice."}),"\n",(0,i.jsx)(t.p,{children:"This lady pointed at one with a particularly large nose, then pointed at one with a particularly small nose, then placed a bet that the big-nosed one had a big stick and the small-nosed one had a small stick, with the size ratio matching the nose ratio. If you don't believe it, open the box and verify. Of course, all male apes were dumbstruck. The two male apes this lady pointed out immediately became turtles withdrawing into their shells, not even having the courage to open the box for verification."}),"\n",(0,i.jsx)(t.p,{children:"This lady's greatest joy is consuming men. Based on this lady's long-term consumption experience, the thesis above has been verified through long-term practice. Not just last night -- countless instances of practice all prove that men are cheap goods, with licentiousness written all over their faces!"}),"\n",(0,i.jsx)(t.p,{children:"From the standpoint of consuming men, this lady discussing this matter now is no different from discussing the features of a garment after buying one. Men are consumer goods, and moreover belong strictly to the category of fast-moving consumer goods, with no difference from menstrual pads. If one must identify a difference: menstrual pads have a certain periodicity, while men have no periodicity -- as long as they're capable, they have time. This is the only characteristic of men as fast-moving consumer goods."}),"\n",(0,i.jsx)(t.p,{children:"From the standpoint of tolerance, let us forgive men's innate cheapness. When the mood strikes, one can also consume them a bit -- otherwise they'll become even cheaper, streaking nude all over the streets, like that seventy-something-year-old stick recently."})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var a=n(96540);const i={},s=a.createContext(i);function o(e){const t=a.useContext(s);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);